import './styles/fonts.css';
import './tailwind.css';
import React from 'react';
import ReactDOM from 'react-dom/client';
import './index.css';
import App from './App';
import reportWebVitals from './reportWebVitals';
import { createBrowserRouter, RouterProvider } from 'react-router-dom';
import { AuthProvider } from './contexts/AuthContext';
import { BrandingProvider } from './contexts/BrandingContext';
import { initPostHog } from './utils/postHogClient';
import { captureAttribution } from './utils/attribution';

initPostHog();
// Grab gclid/utm before any router redirect can strip the query string.
captureAttribution();

// Data router so SettingsPage (and anyone else) can use `useBlocker` to
// intercept in-app navigation when there are unsaved changes. A single
// catch-all route keeps the existing <Routes> tree inside App.js intact.
const router = createBrowserRouter([{ path: '*', element: <App /> }]);

const root = ReactDOM.createRoot(document.getElementById('root'));
// Branding wraps everything, including the auth screens: a white-label
// visitor must see the partner's logo on the login page, before any token
// exists.
const app = (
  <BrandingProvider>
    <AuthProvider>
      <React.StrictMode>
        <RouterProvider router={router} />
      </React.StrictMode>
    </AuthProvider>
  </BrandingProvider>
);

root.render(app);

// If you want to start measuring performance in your app, pass a function
// to log results (for example: reportWebVitals(console.log))
// or send to an analytics endpoint. Learn more: https://bit.ly/CRA-vitals
reportWebVitals();
