// Mock data exports for demo/screenshot mode
export { supplementKeywords } from './supplementKeywords';
export { supplementArticles } from './supplementArticles';
export { supplementSiteSettings } from './supplementSiteSettings';

// Check if mock mode is enabled
export const isMockMode = () => {
  return process.env.REACT_APP_USE_MOCK_DATA === 'true' ||
         localStorage.getItem('useMockData') === 'true';
};

// Enable mock mode (for development)
export const enableMockMode = () => {
  localStorage.setItem('useMockData', 'true');
  window.location.reload();
};

// Disable mock mode
export const disableMockMode = () => {
  localStorage.removeItem('useMockData');
  window.location.reload();
};
