import { initializeApp } from 'firebase/app';
import { getAuth, setPersistence, browserLocalPersistence } from 'firebase/auth';

// Check if this is a preview page BEFORE initializing Firebase
// Preview pages don't need auth and Firebase's cross-tab sync can cause logout issues
const isPreviewPage = window.location.pathname.startsWith('/preview/') ||
                      window.location.pathname.startsWith('/sample/');

const firebaseConfig = {
  apiKey: "AIzaSyBdpcPAyhI4q8uCD7Mc40-Nvhp0Pas9ylE",
  authDomain: "blawgy-368ed.firebaseapp.com",
  projectId: "blawgy-368ed",
  storageBucket: "blawgy-368ed.appspot.com",
  messagingSenderId: "751735189062",
  appId: "1:751735189062:web:395497ee1b8fa489856447",
  measurementId: "G-P9EBGT2N4X"
};

// Only initialize Firebase for non-preview pages
let auth = null;

if (!isPreviewPage) {
  const app = initializeApp(firebaseConfig);
  auth = getAuth(app);

  // Set persistence to local for persistent sessions
  setPersistence(auth, browserLocalPersistence).catch((error) => {
    console.error('Error setting auth persistence:', error);
  });
}

// Set by explicit logout flows right before auth.signOut() so App's auth
// listener can tell an intentional sign-out (clear state, land on /login) from
// a session dying underneath a live tab — cross-tab sign-out, account hopping,
// revoked refresh token — where we keep the page and offer in-place re-auth
// instead of throwing away unsaved work.
const markIntentionalSignOut = () => { window.__blawgyIntentionalSignOut = true; };
const wasIntentionalSignOut = () => window.__blawgyIntentionalSignOut === true;
const clearIntentionalSignOut = () => { window.__blawgyIntentionalSignOut = false; };

export { auth, markIntentionalSignOut, wasIntentionalSignOut, clearIntentionalSignOut };