import React, { useState, useEffect, useRef, useCallback } from 'react';
import axios from 'axios';
import { LoaderIcon } from "lucide-react";

const apiClient = axios.create({
    baseURL: '/internal-tool',
});

function LeadGen() {
    const [passcode, setPasscode] = useState('');
    const [isAuthenticated, setIsAuthenticated] = useState(false);
    const [domain, setDomain] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState(null);
    const [result, setResult] = useState(null);
    const [taskId, setTaskId] = useState(null);
    const [history, setHistory] = useState([]);

    const pollingRef = useRef(null);

    useEffect(() => {
        const storedPasscode = localStorage.getItem('leadgen-passcode');
        if (storedPasscode) {
            setPasscode(storedPasscode);
            setIsAuthenticated(true);
        }

        const storedHistory = localStorage.getItem('leadgen-history');
        if (storedHistory) {
            setHistory(JSON.parse(storedHistory));
        }
    }, []);

    const updateHistory = useCallback((newEntry) => {
        const updatedHistory = [newEntry, ...history];
        setHistory(updatedHistory);
        localStorage.setItem('leadgen-history', JSON.stringify(updatedHistory));
    }, [history]);

    const checkStatus = useCallback(async (currentTaskId) => {
        try {
            const response = await apiClient.get(`/leadgen/${currentTaskId}`);
            const { status, previewUrl, error: taskError } = response.data;

            if (status === 'completed') {
                setResult(previewUrl);
                setIsLoading(false);
                setTaskId(null);
                clearInterval(pollingRef.current);
                updateHistory({
                    domain: domain,
                    url: previewUrl,
                    createdAt: new Date().toISOString(),
                });
                setDomain('');
            } else if (status === 'failed') {
                setError(taskError || 'Generation failed.');
                setIsLoading(false);
                setTaskId(null);
                clearInterval(pollingRef.current);
            }
        } catch (err) {
            setError(err.response?.data?.error || 'Failed to check status.');
            setIsLoading(false);
            setTaskId(null);
            clearInterval(pollingRef.current);
        }
    }, [domain, updateHistory]);

    useEffect(() => {
        if (taskId) {
            pollingRef.current = setInterval(() => {
                checkStatus(taskId);
            }, 5000);
        }

        return () => {
            if (pollingRef.current) {
                clearInterval(pollingRef.current);
            }
        };
    }, [taskId, checkStatus]);

    const handlePasscodeSubmit = (e) => {
        e.preventDefault();
        localStorage.setItem('leadgen-passcode', passcode);
        setIsAuthenticated(true);
    };

    const handleDomainSubmit = async (e) => {
        e.preventDefault();
        setIsLoading(true);
        setError(null);
        setResult(null);

        try {
            const response = await apiClient.post('/leadgen', { domain, passcode });
            setTaskId(response.data.taskId);
        } catch (err) {
            setError(err.response?.data?.error || 'Failed to start generation.');
            setIsLoading(false);
        }
    };

    if (!isAuthenticated) {
        return (
            <div className="flex items-center justify-center h-screen bg-gray-100">
                <form onSubmit={handlePasscodeSubmit} className="p-8 bg-white rounded-lg shadow-md">
                    <h1 className="mb-4 text-xl font-bold">Enter Passcode</h1>
                    <input
                        type="password"
                        value={passcode}
                        onChange={(e) => setPasscode(e.target.value)}
                        className="w-full px-3 py-2 border rounded-md"
                        placeholder="Enter passcode"
                    />
                    <button type="submit" className="w-full px-3 py-2 mt-4 text-white bg-primary rounded-md">
                        Enter
                    </button>
                </form>
            </div>
        );
    }

    return (
        <div className="flex-1 p-4 lg:p-12 overflow-auto pb-20 lg:pb-12">
            <div className="max-w-4xl mx-auto">
                <h2 className="text-xl lg:text-2xl font-bold text-left mb-2">Internal Lead Generation Tool</h2>
                <p className="text-sm text-gray-500 text-left mb-8">
                    Enter a domain to generate a sample article. The process can take up to 5 minutes.
                </p>

                <form onSubmit={handleDomainSubmit} className="p-8 bg-white rounded-lg shadow-md">
                    <div className="mb-4">
                        <label htmlFor="domain" className="block text-sm font-medium text-gray-700 mb-2">Domain</label>
                        <input
                            id="domain"
                            type="text"
                            value={domain}
                            onChange={(e) => setDomain(e.target.value)}
                            className="w-full px-3 py-2 border rounded-md"
                            placeholder="example.com"
                            disabled={isLoading}
                        />
                    </div>
                    <button type="submit" className="w-full px-3 py-2 text-white bg-primary rounded-md flex items-center justify-center" disabled={isLoading}>
                        {isLoading && <LoaderIcon className="animate-spin mr-2" size={18} />}
                        {isLoading ? 'Generating...' : 'Generate Article'}
                    </button>
                </form>

                {error && (
                    <div className="mt-8 p-4 bg-red-100 text-red-700 rounded-lg">
                        <p className="font-bold">Error</p>
                        <p>{error}</p>
                    </div>
                )}

                {result && (
                    <div className="mt-8 p-4 bg-green-100 text-green-700 rounded-lg">
                        <p className="font-bold">Success!</p>
                        <p>
                            Preview URL: <a href={result} target="_blank" rel="noopener noreferrer" className="underline">{result}</a>
                        </p>
                    </div>
                )}

                {history.length > 0 && (
                    <div className="mt-8">
                        <h3 className="text-lg font-bold mb-4">Generation History</h3>
                        <div className="overflow-x-auto bg-white rounded-lg shadow">
                            <table className="min-w-full divide-y divide-gray-200">
                                <thead className="bg-gray-50">
                                    <tr>
                                        <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                            Domain
                                        </th>
                                        <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                            Article Link
                                        </th>
                                        <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                            Date Created
                                        </th>
                                    </tr>
                                </thead>
                                <tbody className="bg-white divide-y divide-gray-200">
                                    {history.map((item, index) => (
                                        <tr key={index}>
                                            <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{item.domain}</td>
                                            <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                                                <a href={item.url} target="_blank" rel="noopener noreferrer" className="text-primary underline">{item.url}</a>
                                            </td>
                                            <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{new Date(item.createdAt).toLocaleString()}</td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
}

export default LeadGen;
